.ssv-img { display: block; width: 100%; max-width: 100%; height: auto; } .ssv-frame { padding: 8px; border: 1px solid #d9dddc; border-radius: 12px; background-color: #ffffff; box-shadow: 0 1px 2px rgba(0,0,0,0.05), 0 18px 36px -24px rgba(6,43,42,0.35); } .ssv-frame.is-hero { border-color: rgba(255,255,255,0.2); box-shadow: 0 30px 60px -30px rgba(0,0,0,0.6); } .ssv-hero-frame { position: relative; z-index: 1; width: 100%; max-width: 520px; } .ssv-hero-tag { margin-top: 12px; color: rgba(255,255,255,0.72); font-size: 13px; text-align: center; }
@media screen and (max-width: 991px) { .ssv-hero-frame { max-width: 560px; } }
@media screen and (max-width: 767px) { .ssv-frame { padding: 5px; border-radius: 10px; } }

.ssv-img.is-strip { width: auto; max-width: none; height: 274px; } .ssv-fineprint.is-wide { max-width: 760px; margin-top: 24px; } .ssv-model { display: grid; grid-template-columns: 4fr 8fr; grid-column-gap: clamp(28px, 4vw, 56px); grid-row-gap: 24px; align-items: start; margin-top: clamp(48px, 6vw, 80px); } .ssv-model.is-wide { grid-template-columns: 1fr; } .ssv-model-text { display: flex; flex-direction: column; align-items: flex-start; max-width: 760px; } .ssv-feature { display: grid; grid-template-columns: 1fr; grid-column-gap: clamp(28px, 4vw, 56px); grid-row-gap: 24px; align-items: start; margin-top: clamp(48px, 6vw, 80px); padding: clamp(20px, 3vw, 40px); border-radius: 20px; background-color: #ffffff; box-shadow: 0 26px 50px -30px rgba(6,43,42,0.45); } .ssv-feature-text { display: grid; grid-template-columns: 7fr 5fr; grid-column-gap: clamp(28px, 4vw, 56px); grid-row-gap: 20px; align-items: start; } .ssv-feature-intro { display: flex; flex-direction: column; align-items: flex-start; } .ssv-feature-side { display: flex; flex-direction: column; padding-top: 8px; } .ssv-artifact { min-width: 0; margin-top: 0; margin-bottom: 0; margin-left: 0; margin-right: 0; padding: clamp(12px, 2vw, 20px); border: 1px solid #e2e2e2; border-radius: 16px; background-color: #ffffff; } .ssv-artifact-media { border-radius: 8px; overflow: hidden; } .ssv-artifact-cap { margin-top: 14px; } .ssv-artifact-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; grid-column-gap: 12px; grid-row-gap: 6px; } .ssv-artifact-title { color: #111111; font-size: 15px; font-weight: 600; } .ssv-credit { padding: 3px 10px; border: 1px solid #e2e2e2; border-radius: 999px; background-color: #f6f6f5; color: #5f5f5f; font-size: 12px; font-weight: 600; } .ssv-credit.is-mine { border-color: #0f6e68; background-color: #0f6e68; color: #ffffff; } .ssv-open { display: inline-block; margin-top: 10px; color: #0f6e68; font-size: 14px; font-weight: 600; text-decoration: none; border-bottom: 1px solid rgba(15,110,104,0.35); } .ssv-open:hover { color: #0a524e; border-bottom-color: #0a524e; } .ssv-open:focus { outline: 3px solid #6fd9cb; outline-offset: 3px; border-radius: 2px; } .ssv-hint { display: none; margin-top: 6px; color: #5f5f5f; font-size: 13px; } .ssv-scroll { overflow-x: auto; overflow-y: hidden; border-radius: 8px; background-color: #f6f6f5; } .ssv-scroll:focus { outline: 3px solid #0f6e68; outline-offset: 2px; } .ssv-levels { display: flex; flex-direction: column; grid-row-gap: 8px; width: 100%; margin-top: 4px; } .ssv-level { padding: 12px 14px; border-radius: 10px; } .ssv-level.is-1 { background-color: #0f6e68; } .ssv-level.is-2 { background-color: #e3f2ef; } .ssv-level.is-3 { border: 1px solid #e2e2e2; background-color: #ffffff; } .ssv-level-h { color: #111111; font-size: 15px; font-weight: 600; } .ssv-level-t { margin-top: 2px; margin-bottom: 0; color: #3d3d3d; font-size: 14.5px; line-height: 1.45; } .ssv-level-h.is-1 { color: #ffffff; } .ssv-level-t.is-1 { color: rgba(255,255,255,0.88); } .ssv-ids { display: grid; grid-template-columns: repeat(3, 1fr); grid-column-gap: 10px; grid-row-gap: 10px; width: 100%; } .ssv-id { padding: 12px 14px; border: 1px solid #e2e2e2; border-radius: 10px; background-color: #ffffff; } .ssv-id-h { color: #0a524e; font-size: 13px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; } .ssv-id-t { margin-top: 4px; margin-bottom: 0; color: #3d3d3d; font-size: 15px; line-height: 1.45; }
@media screen and (max-width: 991px) { .ssv-model { grid-template-columns: 1fr; } .ssv-feature-text { grid-template-columns: 1fr; } }
@media screen and (max-width: 767px) { .ssv-ids { grid-template-columns: 1fr; } .ssv-img.is-strip { height: 220px; } .ssv-img.is-zoom { width: 760px; max-width: none; } .ssv-hint { display: block; } }
